-- ==============================================================================
-- import_marketing_leads.sql
-- Real leads from the Marketing Outreach database (152 businesses).
-- Run ONCE after the migrations (13, 15 to 22). Safe to re-run: skips any business
-- whose name or phone is already in the system.
--
-- Every lead starts as "Needs review" with no messages. Approve them in the review
-- queue (or with approve_import) to create platform threads, assign a salesperson
-- and draft the first message.
--
-- Services: cafés, salons, barbers and trades are pitched Website.
--           Hotels are pitched End-to-End Automation.
-- Emails marked "check" or "unverified" in the sheet are kept in notes, not used.
-- Skipped: True Gents Richmond (Multi-branch, drop); Samuels Barber (same phone as another row).
-- ==============================================================================

SET search_path TO "sales-pipe", public;

DROP TABLE IF EXISTS _import;
CREATE TEMP TABLE _import (business_name text, business_type text, category text, tier text, area text, postcode text, address text, phone text, whatsapp_number text, email text, instagram text, facebook text, existing_website text, google_rating numeric, google_reviews_count int, company_type text, contact_name text, notes text, service text);


WITH new_rows AS (
  SELECT i.* FROM _import i
  WHERE NOT EXISTS (SELECT 1 FROM "sales-pipe".businesses b WHERE lower(b.business_name) = lower(i.business_name))
    AND (i.phone IS NULL OR NOT EXISTS (
          SELECT 1 FROM "sales-pipe".businesses b
          WHERE b.phone_normalised = "sales-pipe".normalise_phone(i.phone)))
    AND (i.email IS NULL OR NOT EXISTS (
          SELECT 1 FROM "sales-pipe".businesses b
          WHERE b.email_normalised = "sales-pipe".normalise_email(i.email)))
),
ins AS (
    business_name, business_type, category, tier, area, postcode, address, phone, whatsapp_number,
    email, instagram, facebook, existing_website, google_rating, google_reviews_count,
    company_type, contact_name, notes
  )
  SELECT business_name, business_type, category, tier, area, postcode, address, phone, whatsapp_number,
         email, instagram, facebook, existing_website, google_rating, google_reviews_count,
         company_type, contact_name, notes
  FROM new_rows
  RETURNING id, business_name
)
SELECT ins.id, ARRAY[n.service], 'Needs review'
FROM ins JOIN new_rows n ON n.business_name = ins.business_name;

DROP TABLE IF EXISTS _import;

-- Check: how many leads per service and type
SELECT o.services_pitched[1] AS service, b.business_type, count(*) AS leads
FROM "sales-pipe".opportunities o JOIN "sales-pipe".businesses b ON b.id = o.business_id
WHERE o.stage = 'Needs review'
GROUP BY 1, 2 ORDER BY 1, 3 DESC;
